1	/****************************************************************************
2	 * apps/examples/jpegenc/jpegenc_main.c
3	 *
4	 * Encode one RGB565 frame to JPEG using the ESP32-P4 hardware JPEG encoder
5	 * (/dev/video1, V4L2 M2M).
6	 *
7	 * Input:  /data/capture.rgb565  (1024x600 RGB565, from camcap)
8	 * Output: /data/capture.jpg
9	 *
10	 * SPDX-License-Identifier: Apache-2.0
11	 ****************************************************************************/
12	
13	#include <syslog.h>
14	#include <nuttx/config.h>
15	#include <stdio.h>
16	#include <stdlib.h>
17	#include <string.h>
18	#include <fcntl.h>
19	#include <unistd.h>
20	#include <errno.h>
21	#include <malloc.h>
22	#include <poll.h>
23	#include <sys/ioctl.h>
24	#include <sys/stat.h>
25	#include <sys/videoio.h>
26	
27	/* RAM debug markers (digits, distinct from arch markers W C i s b e P z c D
28	 * d m n o q E X).  dbg_mark_char() records to the app-only marker address
29	 * (0x5010ffe0) even when the USB console is wedged; the esp_bringup boot
30	 * dump reads it back after a warm reset.  Boot's dbg_putc() markers live at
31	 * 0x5010fff0 and would clobber this address, hence the separation.
32	 */
33	
34	extern void dbg_mark_char(int ch);
35	#define MARK(c) dbg_mark_char(c)
36	
37	/* Print the previous run's last RAM debug marker (survives warm reset). */
38	
39	#define PREV_MARK_ADDR ((volatile uint32_t *)0x5010ffe0)
40	
41	#define M2M_DEV     "/dev/video1"
42	#define IN_FILE     "/tmp/capture.rgb565"
43	#define OUT_FILE    "/tmp/capture.jpg"
44	#define W           1024
45	#define H           600
46	
47	/* RGB565 input frame size (2 bytes/pixel) */
48	#define OUT_SIZE    (W * H * 2)
49	/* JPEG output buffer: driver uses W*H for capture sizeimage, but allow slack */
50	#define CAP_SIZE    (W * H * 2)
51	
52	static int xioctl(int fd, int req, void *arg)
53	{
54	  int r;
55	  do { r = ioctl(fd, req, arg); } while (r == -1 && errno == EINTR);
56	  return r;
57	}
58	
59	int main(int argc, char *argv[])
60	{
61	  int fd = -1, infd = -1, outfd = -1;
62	  int ret = EXIT_FAILURE;
63	  struct v4l2_format fmt;
64	  struct v4l2_requestbuffers req;
65	  struct v4l2_buffer buf;
66	  void *inbuf = NULL;
67	  void *capbuf = NULL;
68	  enum v4l2_buf_type out_type = V4L2_BUF_TYPE_VIDEO_OUTPUT;
69	  enum v4l2_buf_type cap_type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
70	  size_t n;
71	
72	  MARK('@');                     /* main entry */
73	  MARK('A');                     /* before 1st printf */
74	  uint32_t prev = *PREV_MARK_ADDR;
75	  MARK('B');                     /* after skipped printf */
76	  dbg_mark_char('#');            /* RAM-write self-test: expect 0x23 */
77	  MARK('C');                     /* after dbg_mark */
78	  /* fflush(stdout); */
79	  MARK('a');                     /* fflush done, about to allocate input */
80	
81	  /* Generate the RGB565 input frame in memory (skip file I/O for now) */
82	
83	  inbuf = memalign(64, OUT_SIZE);
84	  MARK('b');                     /* input memalign done */
85	  if (!inbuf)
86	    { /* printf("ERROR: memalign input\n"); */ goto out; }
87	  printf("  inbuf @ %p (%d bytes)\n", inbuf, OUT_SIZE);
88	  /* fflush(stdout); */
89	
90	  {
91	    uint8_t *p = (uint8_t *)inbuf;
92	    size_t i;
93	    for (i = 0; i < OUT_SIZE; i++)
94	      {
95	        p[i] = (uint8_t)(i * 31 + (i >> 8));
96	      }
97	  }
98	  n = OUT_SIZE;
99	  MARK('f');                     /* input filled in memory */
100	  printf("  [marker@f] 0x%02x\n", (int)(*PREV_MARK_ADDR));
101	  /* fflush(stdout); */
102	  *PREV_MARK_ADDR = 0xAA;        /* sentinel: survive warm reset */
103	  printf("  [sentinel] 0x%02x\n", (int)(*PREV_MARK_ADDR));
104	  /* fflush(stdout); */
105	  printf("  generated %ld bytes in memory\n", (long)n);
106	  /* fflush(stdout); */
107	
108	  /* Open M2M device */
109	
110	  MARK('0'); /* about to open M2M device */
111	  fd = open(M2M_DEV, O_RDWR, 0);
112	  if (fd < 0)
113	    { /* printf("ERROR: open %s: %d\n", M2M_DEV, errno); */ goto out; }
114	  MARK('1'); /* device open */
115	
116	  /* Set OUTPUT queue format: RGB565 */
117	
118	  memset(&fmt, 0, sizeof(fmt));
119	  fmt.type                = out_type;
120	  fmt.fmt.pix.width       = W;
121	  fmt.fmt.pix.height      = H;
122	  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;
123	  fmt.fmt.pix.field       = V4L2_FIELD_ANY;
124	  if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0)
125	    { /* printf("ERROR: OUTPUT S_FMT: %d\n", errno); */ goto out; }
126	  /* printf("  OUTPUT fmt: %ux%u sizeimage=%u\n",
127	         (unsigned int)fmt.fmt.pix.width, (unsigned int)fmt.fmt.pix.height,
128	         (unsigned int)fmt.fmt.pix.sizeimage); */
129	  /* fflush(stdout); */
130	  MARK('2'); /* output S_FMT ok */
131	
132	  /* Set CAPTURE queue format: JPEG */
133	
134	  memset(&fmt, 0, sizeof(fmt));
135	  fmt.type                = cap_type;
136	  fmt.fmt.pix.width       = W;
137	  fmt.fmt.pix.height      = H;
138	  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
139	  fmt.fmt.pix.field       = V4L2_FIELD_ANY;
140	  if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0)
141	    { /* printf("ERROR: CAPTURE S_FMT: %d\n", errno); */ goto out; }
142	  /* printf("  CAPTURE fmt: %ux%u sizeimage=%u\n",
143	         (unsigned int)fmt.fmt.pix.width, (unsigned int)fmt.fmt.pix.height,
144	         (unsigned int)fmt.fmt.pix.sizeimage); */
145	  /* fflush(stdout); */
146	  MARK('3'); /* capture S_FMT ok */
147	
148	  /* Request buffers on both queues (USERPTR) */
149	
150	  memset(&req, 0, sizeof(req));
151	  req.type   = out_type;
152	  req.memory = V4L2_MEMORY_USERPTR;
153	  req.count  = 2;
154	  if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0)
155	    { /* printf("ERROR: OUTPUT REQBUFS: %d\n", errno); */ goto out; }
156	
157	  memset(&req, 0, sizeof(req));
158	  req.type   = cap_type;
159	  req.memory = V4L2_MEMORY_USERPTR;
160	  req.count  = 2;
161	  if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0)
162	    { /* printf("ERROR: CAPTURE REQBUFS: %d\n", errno); */ goto out; }
163	  MARK('4'); /* reqbufs ok */
164	
165	  /* Allocate capture buffer and queue it on the CAPTURE queue */
166	
167	  capbuf = memalign(64, CAP_SIZE);
168	  if (!capbuf)
169	    { /* printf("ERROR: memalign capture\n"); */ goto out; }
170	
171	  memset(&buf, 0, sizeof(buf));
172	  buf.type      = cap_type;
173	  buf.memory    = V4L2_MEMORY_USERPTR;
174	  buf.index     = 0;
175	  buf.m.userptr = (unsigned long)capbuf;
176	  buf.length    = CAP_SIZE;
177	  if (xioctl(fd, VIDIOC_QBUF, &buf) < 0)
178	    { /* printf("ERROR: CAPTURE QBUF: %d\n", errno); */ goto out; }
179	  MARK('5'); /* capture qbuf ok */
180	
181	  /* Queue input frame on OUTPUT queue */
182	
183	  memset(&buf, 0, sizeof(buf));
184	  buf.type      = out_type;
185	  buf.memory    = V4L2_MEMORY_USERPTR;
186	  buf.index     = 0;
187	  buf.m.userptr = (unsigned long)inbuf;
188	  buf.length    = OUT_SIZE;
189	  buf.bytesused = OUT_SIZE;
190	  if (xioctl(fd, VIDIOC_QBUF, &buf) < 0)
191	    { /* printf("ERROR: OUTPUT QBUF: %d\n", errno); */ goto out; }
192	  MARK('6'); /* output qbuf ok */
193	
194	  /* Start both queues */
195	
196	  if (xioctl(fd, VIDIOC_STREAMON, &out_type) < 0)
197	    { /* printf("ERROR: OUTPUT STREAMON: %d\n", errno); */ goto out; }
198	  if (xioctl(fd, VIDIOC_STREAMON, &cap_type) < 0)
199	    { /* printf("ERROR: CAPTURE STREAMON: %d\n", errno); */ goto out; }
200	  MARK('7'); /* streaming */
201	  /* printf("  streaming...\n"); */
202	  /* fflush(stdout); */
203	
204	  /* Wait for the encoded frame to be ready (DQBUF returns EAGAIN until then) */
205	
206	  {
207	    struct pollfd pfd;
208	    int pret;
209	
210	    pfd.fd     = fd;
211	    pfd.events = POLLIN;
212	    pfd.revents = 0;
213	    for (int tries = 0; tries < 50; tries++)
214	      {
215	        pret = poll(&pfd, 1, 100);
216	        if (pret < 0)
217	          { /* printf("ERROR: poll: %d\n", errno); */ goto out; }
218	        if (pret > 0 && (pfd.revents & POLLIN))
219	          {
220	            MARK('8'); /* poll ready */
221	            break;
222	          }
223	      }
224	
225	    if (pret <= 0 || !(pfd.revents & POLLIN))
226	      {
227	        /* printf("ERROR: timeout waiting for encoded frame\n"); */
228	        goto out;
229	      }
230	  }
231	
232	  /* Dequeue encoded JPEG */
233	
234	  memset(&buf, 0, sizeof(buf));
235	  buf.type   = cap_type;
236	  buf.memory = V4L2_MEMORY_USERPTR;
237	  if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0)
238	    { /* printf("ERROR: CAPTURE DQBUF: %d\n", errno); */ goto out; }
239	  /* printf("  encoded frame %u: %u bytes\n",
240	         (unsigned int)buf.index, (unsigned int)buf.bytesused); */
241	  /* fflush(stdout); */
242	  MARK('9'); /* encoded frame dequeued */
243	  /* Record the JPEG size at a dedicated RAM slot so the boot dump can verify
244	   * the encode actually produced data even when the USB console is lossy.
245	   * 0x5010ffc4 is not used by the boot M dump. */
246	  *((volatile uint32_t *)0x5010ffc4) = (uint32_t)buf.bytesused;
247	
248	  /* Write JPEG to file */
249	
250	  outfd = open(OUT_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
251	  if (outfd < 0)
252	    {
253	      *((volatile uint32_t *)0x5010ffc8) = (uint32_t)errno; /* open errno */
254	      /* printf("ERROR: open %s: %d\n", OUT_FILE, errno); */
255	      goto out;
256	    }
257	  *((volatile uint32_t *)0x5010ffc8) = (uint32_t)outfd;      /* open ok: fd */
258	  MARK('>'); /* capture.jpg opened for write */
259	
260	  n = write(outfd, capbuf, buf.bytesused);
261	  *((volatile uint32_t *)0x5010ffcc) = (uint32_t)n;          /* write ret */
262	  if (n < 0)
263	    { /* printf("ERROR: write: %d\n", errno); */ goto out; }
264	  /* Record the first 4 bytes of the JPEG bitstream (should be FF D8 FF ...
265	   * for a valid SOI) at 0x5010ffb0 so the boot M dump can verify the magic
266	   * even if the console wedges on the final fflush below. */
267	  {
268	    FAR const uint8_t *jp = (FAR const uint8_t *)capbuf;
269	    *((volatile uint32_t *)0x5010ffb0) =
270	      (uint32_t)jp[0] | ((uint32_t)jp[1] << 8) |
271	      ((uint32_t)jp[2] << 16) | ((uint32_t)jp[3] << 24);
272	  }
273	  MARK('z'); /* JPEG written to /tmp/capture.jpg (before console flush) */
274	  /* Record the boot's non-zeroed dispatch counter (0x5010ff00) at the last
275	   * pre-flush marker so the post-hang M dump can tell whether the tick kept
276	   * firing while the final printf was wedged.  Delta vs 0x5010ff00 at dump =
277	   * dispatches during hang + boot. */
278	  *((volatile uint32_t *)0x5010ff08) = *((volatile uint32_t *)0x5010ff00);
279	
280	  /* Pinpoint where the console flush wedges.  0x5010ff9c stage marker:
281	   *   0x5052 "PR" before the printf      -> printf itself is stuck (xmit.lock)
282	   *   0x4646 "FF" printf returned        -> fflush is stuck (tcdrain/xmitsem)
283	   *   0x4642 "FB" fflush returned        -> neither stuck, DONE follows */
284	  *((volatile uint32_t *)0x5010ff9c) = 0x5052;
285	  /* Second dispatch snapshot, taken at the PR stage itself (just before the
286	   * blocking printf).  Also acts as the gate for the driver's block-time
287	   * snapshot in serial.c (jbk == 0x5052 -> record). */
288	  *((volatile uint32_t *)0x5010ff04) = *((volatile uint32_t *)0x5010ff00);
289	  printf("  wrote %ld bytes to %s\n", (long)n, OUT_FILE);
290	  *((volatile uint32_t *)0x5010ff9c) = 0x4646;
291	  /* fflush(stdout); */
292	  *((volatile uint32_t *)0x5010ff9c) = 0x4642;
293	
294	  /* DONE sentinel (only reached on the success path): overwrite the jfd
295	   * slot so a boot M dump can distinguish "jpegnc finished the final
296	   * fflush" from "stuck inside fflush above".  If jfd reads 0x444F4E45 the
297	   * flush returned and the app completed cleanly; if it still reads the
298	   * open fd (4) the process is wedged in the console flush. */
299	  *((volatile uint32_t *)0x5010ffc8) = 0x444F4E45;
300	
301	  /* Cleanup */
302	
303	  xioctl(fd, VIDIOC_QBUF, &buf);
304	  xioctl(fd, VIDIOC_STREAMOFF, &cap_type);
305	  xioctl(fd, VIDIOC_STREAMOFF, &out_type);
306	  ret = EXIT_SUCCESS;
307	
308	out:
309	  if (outfd >= 0) close(outfd);
310	  if (infd >= 0) close(infd);
311	  if (fd >= 0) close(fd);
312	  free(inbuf);
313	  free(capbuf);
314	  return ret;
315	}
