150	{
151	  FAR struct esp_jpeg_s *ctx = priv;
152	
153	  if (fmt->type != V4L2_BUF_TYPE_VIDEO_CAPTURE)
154	    return -EINVAL;
155	  if (fmt->fmt.pix.pixelformat != V4L2_PIX_FMT_JPEG)
156	    return -EINVAL;
157	
158	  /* JPEG encoder output: same dimensions as input */
159	
160	  fmt->fmt.pix.width  = ctx->out_fmt.fmt.pix.width;
161	  fmt->fmt.pix.height = ctx->out_fmt.fmt.pix.height;
162	  fmt->fmt.pix.sizeimage = JPEG_CAP_BUF_SIZE(fmt->fmt.pix.width,
163	                                              fmt->fmt.pix.height);
164	  memcpy(&ctx->cap_fmt, fmt, sizeof(*fmt));
165	  return OK;
166	}
167	
168	static int jpeg_output_s_fmt(FAR void *priv, FAR struct v4l2_format *fmt)
169	{
170	  FAR struct esp_jpeg_s *ctx = priv;
171	
172	  if (fmt->type != V4L2_BUF_TYPE_VIDEO_OUTPUT)
173	    return -EINVAL;
174	  if (fmt->fmt.pix.pixelformat != V4L2_PIX_FMT_RGB565)
175	    return -EINVAL;
176	
177	  /* Clamp to supported range */
178	
179	  fmt->fmt.pix.width  = CLAMP(fmt->fmt.pix.width,  16, JPEG_MAX_WIDTH);
180	  fmt->fmt.pix.height = CLAMP(fmt->fmt.pix.height, 16, JPEG_MAX_HEIGHT);
181	  fmt->fmt.pix.sizeimage = JPEG_OUT_BUF_SIZE(fmt->fmt.pix.width,
182	                                              fmt->fmt.pix.height);
183	  memcpy(&ctx->out_fmt, fmt, sizeof(*fmt));
184	  return OK;
185	}
