#!/usr/bin/env python3
"""Flash then verify NuttX networking on ESP32-P4."""
import serial, time, sys, os, subprocess

# Step 1: Ensure we have a clean flash with nuttx at 0x2000
# (Already done - NuttX is running from previous steps)

def get_port():
    for p in ['/dev/ttyACM0', '/dev/ttyACM1']:
        if os.path.exists(p):
            return p
    return None

def open_serial():
    port = get_port()
    if not port:
        raise RuntimeError("No USB serial port found")
    return serial.Serial(port, 115200, timeout=0.25)

# Step 2: Reset board and capture boot
print("[1] Opening serial port...", flush=True)
ser = None

# Try to connect - the board might be in various states
for attempt in range(10):
    try:
        ser = open_serial()
        break
    except Exception as e:
        if attempt < 9:
            time.sleep(1)
            continue
        raise

print("[2] Resetting board...", flush=True)
ser.setRTS(True); ser.setDTR(False)
time.sleep(0.15)
ser.setDTR(True); time.sleep(0.15)
ser.setDTR(False); time.sleep(0.6)
ser.setRTS(False); ser.setDTR(True)

# Step 3: Read boot output, handle USB reconnection
print("[3] Reading boot output (USB will disconnect/reconnect)...", flush=True)
buf = b''
nsh_found = False
t0 = time.time()

while time.time() - t0 < 90:
    try:
        c = ser.read(4096)
    except (serial.SerialException, OSError):
        # USB disconnected, wait for reconnection
        print(f"[{time.time()-t0:.0f}s] Serial disconnected, waiting...", flush=True)
        try:
            ser.close()
        except:
            pass
        time.sleep(2)
        for retry in range(30):
            port = get_port()
            if port:
                try:
                    ser = serial.Serial(port, 115200, timeout=0.25)
                    print(f"[{time.time()-t0:.0f}s] Reconnected on {port}", flush=True)
                    break
                except:
                    pass
            time.sleep(0.5)
        continue

    if c:
        buf += c
        sys.stdout.buffer.write(c)
        sys.stdout.flush()

    if b'nsh>' in buf and not nsh_found:
        nsh_found = True
        print(f"\n[{time.time()-t0:.0f}s] *** NSH DETECTED! ***", flush=True)
        break

    # If no output for a while and we haven't found NSH, try sending newline
    if time.time() - t0 > 20 and not nsh_found:
        try:
            ser.write(b'\n')
        except:
            pass
        time.sleep(1)

if not nsh_found:
    print("FAILED: NSH not detected within timeout", flush=True)
    print(f"Total output: {len(buf)} bytes", flush=True)
    sys.exit(1)

# Step 4: Network verification
print(f"\n[4] Network verification...", flush=True)
time.sleep(2)

# Drain any pending output
try:
    ser.reset_input_buffer()
except:
    pass

results = {}
tests = [
    ("ifconfig", "ifconfig\n", b'inet addr', b'inet', 4),
    ("nslookup", "nslookup token-plan-cn.xiaomimimo.com\n", b'Address', b'Address', 6),
    ("ping", "ping -c 3 8.8.8.8\n", b'icmp_seq', b'icmp_seq', 10),
    ("https", "wget https://www.baidu.com\n", b'HTTP', b'200', 15),
]

for name, cmd, ok_pattern, detail_pattern, wait_s in tests:
    print(f"--- {name} ---", flush=True)
    try:
        ser.reset_input_buffer()
    except:
        pass

    try:
        ser.write(cmd.encode())
    except (serial.SerialException, OSError):
        print(f"  Serial error, reconnecting...", flush=True)
        try:
            ser.close()
        except:
            pass
        time.sleep(1)
        for retry in range(10):
            port = get_port()
            if port:
                try:
                    ser = serial.Serial(port, 115200, timeout=0.25)
                    break
                except:
                    pass
            time.sleep(0.5)
        time.sleep(1)
        try:
            ser.write(cmd.encode())
        except:
            print(f"  Cannot send command", flush=True)
            results[name] = False
            continue

    time.sleep(0.5)
    out = b''
    t1 = time.time()
    while time.time() - t1 < wait_s:
        try:
            c = ser.read(4096)
        except:
            break
        if c:
            out += c
            sys.stdout.buffer.write(c)
            sys.stdout.flush()
        time.sleep(0.1)

    ok = ok_pattern in out
    results[name] = ok
    status = "OK" if ok else "FAIL"
    print(f"\n  => {status}", flush=True)

# Summary
print(f"\n{'='*60}")
print(f"RESULTS:")
for name, ok in results.items():
    print(f"  {name}: {'PASS' if ok else 'FAIL'}")
all_ok = all(results.values())
print(f"  OVERALL: {'ALL PASS' if all_ok else 'SOME FAILED'}")
print(f"{'='*60}")

ser.close()

#!/usr/bin/env python3
"""Interactive NuttX network diagnostics with careful serial handling."""
import serial, time, sys, os

def get_port():
    for p in ['/dev/ttyACM0', '/dev/ttyACM1']:
        if os.path.exists(p):
            return p
    return None

def run_cmd(ser, cmd, wait_s=3):
    """Send a command and read response."""
    print(f"\n--- {cmd.strip()} ---", flush=True)
    try:
        ser.reset_input_buffer()
    except:
        pass
    # Send command with enough time for each char
    for ch in cmd:
        try:
            ser.write(ch.encode())
            time.sleep(0.02)  # 20ms per char to avoid buffer issues
        except:
            print("  Write error", flush=True)
            return b""
    time.sleep(0.5)
    out = b''
    t0 = time.time()
    while time.time() - t0 < wait_s:
        try:
            c = ser.read(4096)
        except:
            break
        if c:
            out += c
            sys.stdout.buffer.write(c); sys.stdout.flush()
        time.sleep(0.1)
    return out

# Connect
print("[*] Connecting...", flush=True)
port = get_port()
if not port:
    print("No serial port found!")
    sys.exit(1)
ser = serial.Serial(port, 115200, timeout=0.2)
print(f"[*] Connected to {port}", flush=True)

# Clear any pending output and get to NSH prompt
print("[*] Getting to NSH prompt...", flush=True)
try:
    ser.reset_input_buffer()
except:
    pass

# Send some newlines to wake up NSH
for i in range(3):
    try:
        ser.write(b'\r\n')
    except:
        pass
    time.sleep(0.5)
    try:
        c = ser.read(4096)
        if c:
            sys.stdout.buffer.write(c); sys.stdout.flush()
    except:
        pass

# Wait for stable prompt
time.sleep(1)
try:
    c = ser.read(4096)
    if c:
        sys.stdout.buffer.write(c); sys.stdout.flush()
except:
    pass

# Now run diagnostics
# 1. Check help to see available commands
run_cmd(ser, "help\r\n", 5)

# 2. Check network interfaces
run_cmd(ser, "ifconfig\r\n", 4)

# 3. Check Ethernet PHY/status
run_cmd(ser, "eth0\r\n", 3)

# 4. Try DHCP renew
run_cmd(ser, "renew eth0\r\n", 10)

# 5. Check ifconfig again after renew
run_cmd(ser, "ifconfig\r\n", 4)

# 6. Try ping after renew
