#!/usr/bin/env python3
"""Simple NuttX interaction - assume NSH is already running."""
import serial, time, sys, os

def get_port():
    for p in ['/dev/ttyACM0', '/dev/ttyACM1']:
        if os.path.exists(p):
            return p
    return None

port = get_port()
if not port:
    print("No port!", flush=True)
    sys.exit(1)

ser = serial.Serial(port, 115200, timeout=0.5)
print(f"Connected to {port}", flush=True)

# Just send commands with simple read
cmds = [
    ("\r\n", 3),
    ("ifconfig\r\n", 5),
    ("renew eth0\r\n", 15),
    ("ifconfig\r\n", 5),
    ("ping -c 3 8.8.8.8\r\n", 12),
]

for c, wait in cmds:
    print(f"\n>>> {c.strip()}", flush=True)
    time.sleep(1)
    try:
        ser.reset_input_buffer()
        ser.write(c.encode())
    except Exception as e:
        print(f"Error: {e}", flush=True)
        # Reconnect
        try: ser.close()
        except: pass
        time.sleep(1)
        ser = serial.Serial(get_port(), 115200, timeout=0.5)
        try:
            ser.write(c.encode())
        except:
            continue

    t0 = time.time()
    while time.time() - t0 < wait:
        try:
            d = ser.read(4096)
            if d:
                sys.stdout.buffer.write(d); sys.stdout.flush()
        except:
            pass
        time.sleep(0.2)

ser.close()
print("\nDone", flush=True)

