123	static int mimo_tls_connect(FAR void *ctx,
124	                            FAR const char *hostname,
125	                            FAR const char *port,
126	                            unsigned int timeout_sec,
127	                            FAR struct webclient_tls_connection **connp)
128	{
129	  FAR struct mimo_tls_ctx_s *tctx = ctx;
130	  FAR struct mimo_tls_conn_s *conn;
131	  struct hostent *he;
132	  struct sockaddr_in server;
133	  int portnum;
134	  int ret;
135	  int fd;
136	
137	  printf("[mimo] TLS connecting to %s:%s\n", hostname, port);
138	
139	  /* Resolve hostname using gethostbyname (more reliable on NuttX) */
140	
141	  he = gethostbyname(hostname);
142	  if (!he)
143	    {
144	      fprintf(stderr, "[mimo] DNS resolve failed for %s\n", hostname);
145	      return -EIO;
146	    }
147	
148	  /* Create TCP socket and connect */
149	
150	  fd = socket(AF_INET, SOCK_STREAM, 0);
151	  if (fd < 0)
152	    {
153	      fprintf(stderr, "[mimo] socket() failed: %d\n", errno);
154	      return -EIO;
155	    }
156	
157	  portnum = atoi(port);
158	  memset(&server, 0, sizeof(server));
159	  server.sin_family = AF_INET;
160	  server.sin_port = htons(portnum);
161	  memcpy(&server.sin_addr, he->h_addr_list[0], he->h_length);
162	
163	  printf("[mimo] Connecting to %s (%s:%d)\n",
164	         hostname, inet_ntoa(server.sin_addr), portnum);
165	
166	  if (connect(fd, (struct sockaddr *)&server, sizeof(server)) < 0)
167	    {
168	      fprintf(stderr, "[mimo] TCP connect failed: %d\n", errno);
169	      close(fd);
170	      return -EIO;
171	    }
172	
173	  printf("[mimo] TCP connected, starting TLS handshake\n");
174	
175	  /* Allocate TLS connection wrapper */
176	
177	  conn = calloc(1, sizeof(*conn));
178	  if (!conn)
179	    {
180	      close(fd);
181	      return -ENOMEM;
182	    }
183	
184	  conn->fd = fd;
185	  mbedtls_ssl_init(&conn->ssl);
186	
187	  ret = mbedtls_ssl_setup(&conn->ssl, &tctx->conf);
188	  if (ret != 0)
189	    {
190	      fprintf(stderr, "[mimo] TLS ssl setup failed: -0x%x\n", -ret);
191	      goto err;
192	    }
193	
194	  ret = mbedtls_ssl_set_hostname(&conn->ssl, hostname);
195	  if (ret != 0)
196	    {
197	      fprintf(stderr, "[mimo] TLS set hostname failed: -0x%x\n", -ret);
198	      goto err;
199	    }
200	
201	  mbedtls_ssl_set_bio(&conn->ssl, &conn->fd,
202	                       mimo_bio_send, mimo_bio_recv, NULL);
203	
204	  while ((ret = mbedtls_ssl_handshake(&conn->ssl)) != 0)
205	    {
206	      if (ret != MBEDTLS_ERR_SSL_WANT_READ &&
207	          ret != MBEDTLS_ERR_SSL_WANT_WRITE)
208	        {
209	          fprintf(stderr, "[mimo] TLS handshake failed: -0x%x\n", -ret);
210	          goto err;
211	        }
212	    }
213	
214	  printf("[mimo] TLS handshake complete\n");
215	
216	  *connp = (FAR struct webclient_tls_connection *)conn;
217	  return 0;
218	
219	err:
220	  mbedtls_ssl_free(&conn->ssl);
221	  close(conn->fd);
222	  free(conn);
223	  return -EIO;
224	}
