377	/**
378	 * Sink callback for webclient: accumulates response body chunks.
379	 */
380	
381	static int http_sink_callback(FAR char **buffer, int offset,
382	                              int datend, FAR int *buflen,
383	                              FAR void *arg)
384	{
385	  FAR struct http_resp_buf_s *resp = arg;
386	  int len = datend - offset;
387	
388	  if (len <= 0)
389	    {
390	      return 0;
391	    }
392	
393	  /* Grow buffer if needed */
394	
395	  while (resp->len + len + 1 > resp->cap)
396	    {
397	      size_t newcap = resp->cap ? resp->cap * 2 : 4096;
398	      char *newdata = realloc(resp->data, newcap);
399	      if (!newdata)
400	        {
401	          fprintf(stderr, "[mimo] OOM in sink callback\n");
402	          return -ENOMEM;
403	        }
404	
405	      resp->data = newdata;
406	      resp->cap = newcap;
407	    }
408	
409	  memcpy(resp->data + resp->len, &((*buffer)[offset]), len);
410	  resp->len += len;
411	  resp->data[resp->len] = '\0';
412	  return 0;
413	}
