517	    }
518	
519	  /* Tools (OpenAI function calling format) */
520	
521	#ifdef CONFIG_MIMO_ENABLE_TOOLS
522	  if (req->tools_json && strlen(req->tools_json) > 0)
523	    {
524	      cJSON *tools = cJSON_Parse(req->tools_json);
525	      if (tools)
526	        {
527	          cJSON_AddItemToObject(root, "tools", tools);
528	        }
529	    }
530	#endif
531	
532	  return root;
533	}
534	
535	/**
536	 * Parse MiMo response.
537	 *
538	 * Handles standard OpenAI fields plus MiMo's reasoning_content
539	 * extension returned alongside tool_calls in thinking mode.
540	 */
541	
542	static int parse_response(const char *json_str,
543	                          struct mimo_chat_resp_s *resp)
544	{
545	  cJSON *root;
546	  cJSON *choices;
547	  cJSON *choice;
548	  cJSON *message;
549	  cJSON *content;
550	  cJSON *tool_calls;
551	
552	  memset(resp, 0, sizeof(*resp));
553	
554	  root = cJSON_Parse(json_str);
555	  if (!root)
556	    {
557	      fprintf(stderr, "[mimo] JSON parse error\n");
558	      return -1;
559	    }
560	
561	  /* Check for API error */
562	
563	  cJSON *error = cJSON_GetObjectItem(root, "error");
564	  if (error)
565	    {
566	      cJSON *errmsg = cJSON_GetObjectItem(error, "message");
567	      fprintf(stderr, "[mimo] API error: %s\n",
568	              errmsg ? errmsg->valuestring : "unknown");
569	      cJSON_Delete(root);
570	      return -1;
571	    }
572	
573	  choices = cJSON_GetObjectItem(root, "choices");
574	  if (!choices || cJSON_GetArraySize(choices) == 0)
575	    {
576	      fprintf(stderr, "[mimo] No choices in response\n");
577	      cJSON_Delete(root);
578	      return -1;
579	    }
580	
581	  choice = cJSON_GetArrayItem(choices, 0);
582	  message = cJSON_GetObjectItem(choice, "message");
583	  if (!message)
584	    {
585	      cJSON_Delete(root);
586	      return -1;
587	    }
588	
589	  /* Extract reasoning_content (MiMo thinking mode) */
590	
591	  cJSON *reasoning = cJSON_GetObjectItem(message, "reasoning_content");
592	  if (reasoning && reasoning->valuestring)
593	    {
594	      resp->reasoning_content = strdup(reasoning->valuestring);
595	      printf("[mimo] Thinking: %.80s%s\n",
596	             reasoning->valuestring,
597	             strlen(reasoning->valuestring) > 80 ? "..." : "");
598	    }
599	
600	  /* Extract content */
601	
602	  content = cJSON_GetObjectItem(message, "content");
603	  if (content && content->valuestring)
604	    {
605	      resp->content = strdup(content->valuestring);
606	    }
607	
608	  /* Check for tool calls (OpenAI format) */
609	
610	  tool_calls = cJSON_GetObjectItem(message, "tool_calls");
611	  if (tool_calls && cJSON_GetArraySize(tool_calls) > 0)
612	    {
613	      cJSON *tc = cJSON_GetArrayItem(tool_calls, 0);
614	      cJSON *tc_id = cJSON_GetObjectItem(tc, "id");
615	      cJSON *func = cJSON_GetObjectItem(tc, "function");
616	
617	      if (func)
618	        {
619	          cJSON *fname = cJSON_GetObjectItem(func, "name");
620	          cJSON *fargs = cJSON_GetObjectItem(func, "arguments");
621	
622	          resp->is_tool_use = true;
623	
624	          if (tc_id && tc_id->valuestring)
625	            {
626	              resp->tool_call_id = strdup(tc_id->valuestring);
627	            }
628	
629	          if (fname && fname->valuestring)
630	            {
631	              resp->tool_name = strdup(fname->valuestring);
632	            }
633	
634	          if (fargs && fargs->valuestring)
635	            {
636	              resp->tool_input = strdup(fargs->valuestring);
637	            }
638	        }
639	    }
640	
641	  cJSON_Delete(root);
642	  return 0;
643	}
