645	/****************************************************************************
646	 * Public Functions
647	 ****************************************************************************/
648	
649	int mimo_provider_init(const char *api_key, const char *base_url)
650	{
651	  if (!api_key || strlen(api_key) == 0)
652	    {
653	      fprintf(stderr, "[mimo] API key not configured\n");
654	      return -1;
655	    }
656	
657	  strncpy(g_api_key, api_key, sizeof(g_api_key) - 1);
658	  strncpy(g_base_url, base_url, sizeof(g_base_url) - 1);
659	
660	  printf("[mimo] Provider initialized\n");
661	  printf("[mimo] Endpoint: %s\n", g_base_url);
662	  printf("[mimo] Thinking mode: %s\n",
663	#ifdef CONFIG_MIMO_ENABLE_THINKING
664	         "enabled"
665	#else
666	         "disabled"
667	#endif
668	         );
669	  return 0;
670	}
671	
672	int mimo_provider_chat(const struct mimo_chat_req_s *req,
673	                       struct mimo_chat_resp_s *resp)
674	{
675	  cJSON *body;
676	  char *body_str;
677	  char auth_header[300];
678	  const char *headers[2];
679	  struct webclient_context ctx;
680	  struct http_resp_buf_s resp_buf;
681	  char *work_buf;
682	  int ret;
683	
684	  body = build_request_body(req);
685	  if (!body)
686	    {
687	      return -1;
688	    }
689	
690	  body_str = cJSON_PrintUnformatted(body);
691	  cJSON_Delete(body);
692	
693	  if (!body_str)
694	    {
695	      return -1;
696	    }
697	
698	  printf("[mimo] POST %s (%d bytes)\n",
699	         g_base_url, (int)strlen(body_str));
700	
701	  /* Prepare HTTP headers */
702	
703	  snprintf(auth_header, sizeof(auth_header),
704	           "Authorization: Bearer %s", g_api_key);
705	  headers[0] = "Content-Type: application/json";
706	  headers[1] = auth_header;
707	
708	  /* Allocate work buffer for webclient (used for HTTP header I/O) */
709	
710	  work_buf = malloc(2048);
711	  if (!work_buf)
712	    {
713	      free(body_str);
714	      return -1;
715	    }
716	
717	  /* Initialize response accumulator */
718	
719	  memset(&resp_buf, 0, sizeof(resp_buf));
720	
721	  /* Set up webclient context */
722	
723	  webclient_set_defaults(&ctx);
724	  ctx.protocol_version = WEBCLIENT_PROTOCOL_VERSION_HTTP_1_1;
725	  ctx.method   = "POST";
726	  ctx.url      = g_base_url;
727	  ctx.buffer   = work_buf;
728	  ctx.buflen   = 2048;
729	  ctx.headers  = headers;
730	  ctx.nheaders = 2;
731	  ctx.sink_callback     = http_sink_callback;
732	  ctx.sink_callback_arg = &resp_buf;
733	  ctx.timeout_sec       = 60;
734	
735	#ifdef CONFIG_CRYPTO_MBEDTLS
736	  /* Enable TLS for HTTPS */
737	
738	  ret = mimo_tls_init();
739	  if (ret < 0)
740	    {
741	      fprintf(stderr, "[mimo] TLS init failed\n");
742	      free(work_buf);
743	      free(body_str);
744	      return -1;
745	    }
746	
747	  ctx.tls_ops = &g_mimo_tls_ops;
748	  ctx.tls_ctx = &g_tls_ctx;
749	#endif
750	
751	  webclient_set_static_body(&ctx, body_str, strlen(body_str));
752	
753	  ret = webclient_perform(&ctx);
754	
755	  free(work_buf);
756	  free(body_str);
757	
758	  if (ret < 0)
759	    {
760	      fprintf(stderr, "[mimo] HTTP request failed: %d\n", ret);
761	      if (resp_buf.data)
762	        {
763	          free(resp_buf.data);
764	        }
765	
766	      return -1;
767	    }
768	
769	  printf("[mimo] HTTP %d, response %zu bytes\n",
770	         ctx.http_status, resp_buf.len);
771	
772	  if (ctx.http_status != 200 || !resp_buf.data)
773	    {
774	      fprintf(stderr, "[mimo] HTTP error %d: %s\n",
775	              ctx.http_status,
776	              resp_buf.data ? resp_buf.data : "(empty)");
777	      if (resp_buf.data)
778	        {
779	          free(resp_buf.data);
780	        }
781	
782	      return -1;
783	    }
784	
785	  /* Parse the JSON response */
786	
787	  ret = parse_response(resp_buf.data, resp);
788	  free(resp_buf.data);
789	
790	  return ret;
791	}
792	
793	void mimo_chat_resp_free(struct mimo_chat_resp_s *resp)
794	{
795	  if (resp->content)
796	    {
797	      free(resp->content);
798	      resp->content = NULL;
799	    }
800	
801	  if (resp->tool_call_id)
802	    {
803	      free(resp->tool_call_id);
804	      resp->tool_call_id = NULL;
805	    }
806	
807	  if (resp->tool_name)
808	    {
809	      free(resp->tool_name);
810	      resp->tool_name = NULL;
811	    }
812	
813	  if (resp->tool_input)
814	    {
815	      free(resp->tool_input);
816	      resp->tool_input = NULL;
817	    }
818	
819	  if (resp->reasoning_content)
820	    {
821	      free(resp->reasoning_content);
822	      resp->reasoning_content = NULL;
823	    }
824	}
