146	
147	      if (resp.is_tool_use && resp.tool_name)
148	        {
149	          /* Tool use: add assistant message with reasoning_content,
150	           * execute tool, add result, and continue loop.
151	           */
152	
153	          printf("[mimo:agent] Tool call: %s\n", resp.tool_name);
154	
155	          history_add(MIMO_ROLE_ASSISTANT, resp.content,
156	                      resp.tool_call_id, resp.reasoning_content);
