 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <unistd.h>
#include <netutils/cJSON.h>
#include <netutils/webclient.h>

#ifdef CONFIG_CRYPTO_MBEDTLS
#  include <mbedtls/ssl.h>
#  include <mbedtls/entropy.h>
#  include <mbedtls/ctr_drbg.h>
#endif

#include "include/mimo_client.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define HTTP_WORK_BUF_SIZE  4096
#define HTTP_RESP_BUF_INIT  4096

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* Response accumulator for webclient sink callback */

struct resp_buf_s
{
  char  *data;
  size_t len;
  size_t cap;
};

#ifdef CONFIG_CRYPTO_MBEDTLS

/* TLS context */

struct tls_ctx_s
{
  mbedtls_entropy_context  entropy;
  mbedtls_ctr_drbg_context ctr_drbg;
  mbedtls_ssl_config       conf;
};

/* TLS connection wrapper */

struct tls_conn_s
{
  mbedtls_ssl_context  ssl;
  int                  fd;
};

#endif /* CONFIG_CRYPTO_MBEDTLS */

/****************************************************************************
 * Private Data
 ****************************************************************************/

#ifdef CONFIG_CRYPTO_MBEDTLS
static struct tls_ctx_s g_tls_ctx;
static bool g_tls_ready = false;
#endif

/****************************************************************************
 * Private Functions - TLS
 ****************************************************************************/

#ifdef CONFIG_CRYPTO_MBEDTLS

static int bio_send(void *ctx, const unsigned char *buf, size_t len)
{
  int fd = *(int *)ctx;
  ssize_t ret = send(fd, buf, len, 0);
  return (ret < 0) ? -EIO : (int)ret;
}

static int bio_recv(void *ctx, unsigned char *buf, size_t len)
{
  int fd = *(int *)ctx;
  ssize_t ret = recv(fd, buf, len, 0);
  if (ret < 0) return -EIO;
  if (ret == 0) return MBEDTLS_ERR_SSL_WANT_READ;
  return (int)ret;
}

static int tls_connect(void *ctx, const char *hostname, const char *port,
                       unsigned int timeout_sec,
                       struct webclient_tls_connection **connp)
{
  struct tls_ctx_s *tctx = ctx;
  struct tls_conn_s *conn;
  struct hostent *he;
  struct sockaddr_in server;
  int portnum;
  int ret;
  int fd;

  he = gethostbyname(hostname);
  if (!he)
    {
      fprintf(stderr, "[mimo_client] DNS resolve failed for %s\n", hostname);
      return -EIO;
    }

  fd = socket(AF_INET, SOCK_STREAM, 0);
  if (fd < 0)
    {
      fprintf(stderr, "[mimo_client] socket() failed: %d\n", errno);
      return -EIO;
    }

  portnum = atoi(port);
  memset(&server, 0, sizeof(server));
  server.sin_family = AF_INET;
  server.sin_port = htons(portnum);
  memcpy(&server.sin_addr, he->h_addr_list[0], he->h_length);

  if (connect(fd, (struct sockaddr *)&server, sizeof(server)) < 0)
    {
      fprintf(stderr, "[mimo_client] TCP connect failed: %d\n", errno);
      close(fd);
      return -EIO;
    }

  conn = calloc(1, sizeof(*conn));
  if (!conn)
    {
      close(fd);
      return -ENOMEM;
    }

  conn->fd = fd;
  mbedtls_ssl_init(&conn->ssl);

  ret = mbedtls_ssl_setup(&conn->ssl, &tctx->conf);
  if (ret != 0) goto err;

  ret = mbedtls_ssl_set_hostname(&conn->ssl, hostname);
  if (ret != 0) goto err;

  mbedtls_ssl_set_bio(&conn->ssl, &conn->fd, bio_send, bio_recv, NULL);

  while ((ret = mbedtls_ssl_handshake(&conn->ssl)) != 0)
    {
      if (ret != MBEDTLS_ERR_SSL_WANT_READ &&
          ret != MBEDTLS_ERR_SSL_WANT_WRITE)
        {
          fprintf(stderr, "[mimo_client] TLS handshake failed: -0x%x\n",
                  -ret);
          goto err;
        }
    }

  *connp = (struct webclient_tls_connection *)conn;
  return 0;

err:
  mbedtls_ssl_free(&conn->ssl);
  close(conn->fd);
  free(conn);
  return -EIO;
}

static ssize_t tls_send(void *ctx, struct webclient_tls_connection *base,
                        const void *buf, size_t len)
{
  struct tls_conn_s *conn = (struct tls_conn_s *)base;
  (void)ctx;
  int ret = mbedtls_ssl_write(&conn->ssl, buf, len);
  if (ret < 0)
    {
      return (ret == MBEDTLS_ERR_SSL_WANT_WRITE) ? 0 : -EIO;
    }

  return ret;
}

static ssize_t tls_recv(void *ctx, struct webclient_tls_connection *base,
                        void *buf, size_t len)
{
  struct tls_conn_s *conn = (struct tls_conn_s *)base;
  (void)ctx;
  int ret = mbedtls_ssl_read(&conn->ssl, buf, len);
  if (ret < 0)
    {
      if (ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY ||
          ret == MBEDTLS_ERR_SSL_WANT_READ)
        {
          return 0;
        }

      return -EIO;
    }

  return ret;
}

static int tls_close(void *ctx, struct webclient_tls_connection *base)
{
  struct tls_conn_s *conn = (struct tls_conn_s *)base;
  (void)ctx;
  mbedtls_ssl_close_notify(&conn->ssl);
  mbedtls_ssl_free(&conn->ssl);
  close(conn->fd);
  free(conn);
  return 0;
}

static int tls_poll_info(void *ctx, struct webclient_tls_connection *base,
                         struct webclient_poll_info *info)
{
  struct tls_conn_s *conn = (struct tls_conn_s *)base;
  (void)ctx;
  info->fd = conn->fd;
  info->flags = WEBCLIENT_POLL_INFO_WANT_READ;
  return 0;
}

static const struct webclient_tls_ops g_tls_ops =
{
  .connect        = tls_connect,
  .send           = tls_send,
  .recv           = tls_recv,
  .close          = tls_close,
  .get_poll_info  = tls_poll_info,
  .init_connection = NULL,
};

static int tls_init(void)
{
  int ret;

  if (g_tls_ready) return 0;

  mbedtls_entropy_init(&g_tls_ctx.entropy);
  mbedtls_ctr_drbg_init(&g_tls_ctx.ctr_drbg);
  mbedtls_ssl_config_init(&g_tls_ctx.conf);

  ret = mbedtls_ctr_drbg_seed(&g_tls_ctx.ctr_drbg,
                               mbedtls_entropy_func,
                               &g_tls_ctx.entropy,
                               (const unsigned char *)"mimo_client", 11);
  if (ret != 0) return -1;

  ret = mbedtls_ssl_config_defaults(&g_tls_ctx.conf,
                                     MBEDTLS_SSL_IS_CLIENT,
                                     MBEDTLS_SSL_TRANSPORT_STREAM,
                                     MBEDTLS_SSL_PRESET_DEFAULT);
  if (ret != 0) return -1;

  mbedtls_ssl_conf_authmode(&g_tls_ctx.conf, MBEDTLS_SSL_VERIFY_NONE);
  mbedtls_ssl_conf_rng(&g_tls_ctx.conf, mbedtls_ctr_drbg_random,
                        &g_tls_ctx.ctr_drbg);

  g_tls_ready = true;
  return 0;
}

static void tls_deinit(void)
{
  if (!g_tls_ready) return;
  mbedtls_ssl_config_free(&g_tls_ctx.conf);
  mbedtls_ctr_drbg_free(&g_tls_ctx.ctr_drbg);
  mbedtls_entropy_free(&g_tls_ctx.entropy);
  g_tls_ready = false;
}

#endif /* CONFIG_CRYPTO_MBEDTLS */

/****************************************************************************
 * Private Functions - HTTP Sink
 ****************************************************************************/

static int sink_callback(char **buffer, int offset, int datend,
                         int *buflen, void *arg)
{
  struct resp_buf_s *resp = arg;
  int len = datend - offset;

  if (len <= 0) return 0;

  while (resp->len + len + 1 > resp->cap)
    {
      size_t newcap = resp->cap ? resp->cap * 2 : HTTP_RESP_BUF_INIT;
      char *newdata = realloc(resp->data, newcap);
      if (!newdata) return -ENOMEM;
      resp->data = newdata;
      resp->cap = newcap;
    }

  memcpy(resp->data + resp->len, &((*buffer)[offset]), len);
  resp->len += len;
  resp->data[resp->len] = '\0';
  return 0;
}

/****************************************************************************
 * Private Functions - Response Parser
 ****************************************************************************/

static int parse_chat_response(const char *json_str,
                               struct mimo_rsp_s *rsp)
{
  cJSON *root;
  cJSON *choices;
  cJSON *choice;
  cJSON *message;
  cJSON *content;
  cJSON *audio;
  cJSON *audio_data_item;

  root = cJSON_Parse(json_str);
  if (!root)
    {
      snprintf(rsp->error_msg, sizeof(rsp->error_msg),
               "JSON parse error");
      rsp->error_code = -1;
      return -1;
    }

  /* Check for API-level error */

  cJSON *error = cJSON_GetObjectItem(root, "error");
  if (error)
    {
      cJSON *errmsg = cJSON_GetObjectItem(error, "message");
      snprintf(rsp->error_msg, sizeof(rsp->error_msg), "API: %s",
               errmsg ? errmsg->valuestring : "unknown");
      rsp->error_code = -2;
      cJSON_Delete(root);
      return -1;
    }

  choices = cJSON_GetObjectItem(root, "choices");
  if (!choices || cJSON_GetArraySize(choices) == 0)
    {
      snprintf(rsp->error_msg, sizeof(rsp->error_msg),
               "No choices in response");
      rsp->error_code = -3;
      cJSON_Delete(root);
      return -1;
    }

  choice = cJSON_GetArrayItem(choices, 0);
  message = cJSON_GetObjectItem(choice, "message");
  if (!message)
    {
      snprintf(rsp->error_msg, sizeof(rsp->error_msg),
               "No message in choice");
      rsp->error_code = -4;
      cJSON_Delete(root);
      return -1;
    }

  /* Extract text content */

  content = cJSON_GetObjectItem(message, "content");
  if (content && content->valuestring)
    {
      rsp->content = strdup(content->valuestring);
    }

  /* Extract audio data (TTS response) */

  audio = cJSON_GetObjectItem(message, "audio");
  if (audio)
    {
      audio_data_item = cJSON_GetObjectItem(audio, "data");
      if (audio_data_item && audio_data_item->valuestring)
        {
          /* Audio data is base64-encoded, store as-is for caller to decode */
          rsp->audio_data = (uint8_t *)strdup(audio_data_item->valuestring);
          rsp->audio_len = strlen((char *)rsp->audio_data);
        }
    }

  cJSON_Delete(root);
  return 0;
}

