/****************************************************************************
 * Name: mimo_http_post
 *
 * Description:
 *   POST a JSON body string to the MiMo API endpoint via TLS.
 *   On success the parsed response is placed in rsp.
 *   Returns 0 on success, <0 on error.
 *
 ****************************************************************************/

int mimo_http_post(const char *json_body, struct mimo_rsp_s *rsp)
{
  char auth_header[300];
  const char *headers[2];
  struct webclient_context ctx;
  struct resp_buf_s resp_buf;
  char *work_buf;
  char url[256];
  int ret;

  memset(&resp_buf, 0, sizeof(resp_buf));

  /* Build URL */

  snprintf(url, sizeof(url), "https://%s:%s/v1/chat/completions",
           MIMO_HOST, MIMO_PORT);

  /* Auth header */

  snprintf(auth_header, sizeof(auth_header),
           "Authorization: Bearer %s", MIMO_API_KEY);
  headers[0] = "Content-Type: application/json";
  headers[1] = auth_header;

  /* Work buffer for webclient */

  work_buf = malloc(HTTP_WORK_BUF_SIZE);
  if (!work_buf)
    {
      snprintf(rsp->error_msg, sizeof(rsp->error_msg), "OOM");
      rsp->error_code = -10;
      return -1;
    }

  /* Configure webclient */

  webclient_set_defaults(&ctx);
  ctx.protocol_version = WEBCLIENT_PROTOCOL_VERSION_HTTP_1_1;
  ctx.method   = "POST";
  ctx.url      = url;
  ctx.buffer   = work_buf;
  ctx.buflen   = HTTP_WORK_BUF_SIZE;
  ctx.headers  = headers;
  ctx.nheaders = 2;
  ctx.sink_callback     = sink_callback;
  ctx.sink_callback_arg = &resp_buf;
  ctx.timeout_sec       = 60;

#ifdef CONFIG_CRYPTO_MBEDTLS
  ctx.tls_ops = &g_tls_ops;
  ctx.tls_ctx = &g_tls_ctx;
#endif

  webclient_set_static_body(&ctx, json_body, strlen(json_body));

  ret = webclient_perform(&ctx);

  free(work_buf);

  if (ret < 0)
    {
      snprintf(rsp->error_msg, sizeof(rsp->error_msg),
               "HTTP request failed: %d", ret);
      rsp->error_code = ret;
      free(resp_buf.data);
      return -1;
    }

  rsp->http_status = ctx.http_status;

  if (ctx.http_status != 200 || !resp_buf.data)
    {
      snprintf(rsp->error_msg, sizeof(rsp->error_msg),
               "HTTP %d", ctx.http_status);
      rsp->error_code = ctx.http_status;
      free(resp_buf.data);
      return -1;
    }

  /* Parse JSON response */

  ret = parse_chat_response(resp_buf.data, rsp);
  free(resp_buf.data);
  return ret;
}

void mimo_free_response(struct mimo_rsp_s *rsp)
{
  if (rsp->content)
    {
      free(rsp->content);
      rsp->content = NULL;
    }

  if (rsp->audio_data)
    {
      free(rsp->audio_data);
      rsp->audio_data = NULL;
      rsp->audio_len = 0;
    }
}

