/****************************************************************************
 * Name: mimo_tts_build_body
 *
 * Description:
 *   Build the JSON body for TTS MiMo API call.
 *   TTS requires "mimo-v2.5-tts" model with the text placed in an
 *   assistant-role message.
 *
 *   {
 *     "model": "mimo-v2.5-tts",
 *     "messages": [
 *       {"role": "user", "content": "Please read this text aloud."},
 *       {"role": "assistant", "content": "<text_to_speak>"}
 *     ]
 *   }
 *
 ****************************************************************************/

char *mimo_tts_build_body(const struct mimo_req_s *req)
{
  cJSON *root;
  cJSON *messages;
  cJSON *user_msg;
  cJSON *asst_msg;
  char *body;

  root = cJSON_CreateObject();
  if (!root) return NULL;

  cJSON_AddStringToObject(root, "model", "mimo-v2.5-tts");
  cJSON_AddNumberToObject(root, "top_p", 0.95);
  cJSON_AddNumberToObject(root, "max_tokens", 4096);

  messages = cJSON_AddArrayToObject(root, "messages");

  /* User message: instruction to read text aloud */

  user_msg = cJSON_CreateObject();
  cJSON_AddStringToObject(user_msg, "role", "user");
  cJSON_AddStringToObject(user_msg, "content", "Please read this aloud.");
  cJSON_AddItemToArray(messages, user_msg);

  /* Assistant message: the text to speak */

  asst_msg = cJSON_CreateObject();
  cJSON_AddStringToObject(asst_msg, "role", "assistant");
  cJSON_AddStringToObject(asst_msg, "content",
