/**
 * serctl - Simple serial command sender with timeout-based reading.
 * Usage: serctl <device> <timeout_ms> <command...>
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: serctl <device> <timeout_ms> <command...>\n");
        return 1;
    }

    const char *dev = argv[1];
    int timeout_ms = atoi(argv[2]);
    char cmd[512] = {0};

    // Build command string
    for (int i = 3; i < argc; i++) {
        strcat(cmd, argv[i]);
        if (i < argc - 1) strcat(cmd, " ");
    }
    strcat(cmd, "\r\n");

    int fd = open(dev, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    struct termios tio;
    tcgetattr(fd, &tio);
    cfmakeraw(&tio);
    tio.c_cflag = CS8 | CREAD | CLOCAL;
    tio.c_cc[VMIN] = 0;
    tio.c_cc[VTIME] = 0;
    cfsetospeed(&tio, B115200);
    cfsetispeed(&tio, B115200);
    tcsetattr(fd, TCSANOW, &tio);

    // Drain any pending input
    char drain[4096];
    while (read(fd, drain, sizeof(drain)) > 0) {}

    // Send command
    write(fd, cmd, strlen(cmd));

    // Read response with timeout
    char buf[4096];
    int total = 0;
    int elapsed = 0;
    int interval = 100; // Poll every 100ms

    while (elapsed < timeout_ms) {
        fd_set rfds;
        struct timeval tv;
        FD_ZERO(&rfds);
        FD_SET(fd, &rfds);
        tv.tv_sec = 0;
        tv.tv_usec = interval * 1000;

        int ret = select(fd + 1, &rfds, NULL, NULL, &tv);
        if (ret > 0) {
            int n = read(fd, buf + total, sizeof(buf) - 1 - total);
            if (n > 0) {
                total += n;
                buf[total] = '\0';
            } else if (n == 0) {
                break; // EOF
            }
        } else if (ret < 0 && errno != EINTR) {
            break;
        }
        elapsed += interval;
    }

    if (total > 0) {
        // Print only printable content
        for (int i = 0; i < total; i++) {
            unsigned char c = buf[i];
            if (c >= 32 && c <= 126) putchar(c);
            else if (c == '\n' || c == '\r') putchar('\n');
            else if (c == '\t') putchar('\t');
        }
        putchar('\n');
    }

    close(fd);
    return 0;
}

