27	/****************************************************************************
28	 * Name: mimo_request
29	 *
30	 * Description:
31	 *   Send a multimodal request to the MiMo API.
32	 *   Dispatches to the modality-specific body builder, POSTs via TLS,
33	 *   and parses the response.
34	 *
35	 ****************************************************************************/
36	
37	int mimo_request(const struct mimo_req_s *req, struct mimo_rsp_s *rsp)
38	{
39	  const struct mimo_modality_cfg_s *cfg;
40	  char *body;
41	  int ret;
42	
43	  if (!req || !rsp)
44	    {
45	      return -1;
46	    }
47	
48	  memset(rsp, 0, sizeof(*rsp));
49	
50	  if (req->modality >= MIMO_MODALITY_MAX)
51	    {
52	      snprintf(rsp->error_msg, sizeof(rsp->error_msg),
53	               "Invalid modality: %d", req->modality);
54	      rsp->error_code = -1;
55	      return -1;
56	    }
57	
58	  cfg = &g_modality_table[req->modality];
59	
60	  /* Build the JSON request body */
61	
62	  body = cfg->build_body(req);
63	  if (!body)
64	    {
65	      snprintf(rsp->error_msg, sizeof(rsp->error_msg),
66	               "Failed to build request body");
67	      rsp->error_code = -2;
68	      return -1;
69	    }
70	
71	  /* POST to the MiMo API */
72	
73	  ret = mimo_http_post(body, rsp);
74	  free(body);
75	
76	  if (ret < 0)
77	    {
78	      /* Error already set by mimo_http_post */
79	      return ret;
80	    }
81	
82	  /* Modality-specific response parsing */
83	
84	  ret = cfg->parse_resp(NULL, rsp);
85	
86	  return ret;
87	}
