88	
89	static int bio_send(void *ctx, const unsigned char *buf, size_t len)
90	{
91	  int fd = *(int *)ctx;
92	  ssize_t ret = send(fd, buf, len, 0);
93	  return (ret < 0) ? -EIO : (int)ret;
94	}
95	
96	static int bio_recv(void *ctx, unsigned char *buf, size_t len)
97	{
98	  int fd = *(int *)ctx;
99	  ssize_t ret = recv(fd, buf, len, 0);
100	  if (ret < 0) return -EIO;
101	  if (ret == 0) return MBEDTLS_ERR_SSL_WANT_READ;
102	  return (int)ret;
103	}
104	
105	static int tls_init(void)
106	{
107	  int ret;
108	
109	  if (g_tls_ready) return 0;
110	
111	  mbedtls_entropy_init(&g_tls_ctx.entropy);
112	  mbedtls_ctr_drbg_init(&g_tls_ctx.ctr_drbg);
113	  mbedtls_ssl_config_init(&g_tls_ctx.conf);
114	
115	  ret = mbedtls_ctr_drbg_seed(&g_tls_ctx.ctr_drbg,
116	                               mbedtls_entropy_func,
117	                               &g_tls_ctx.entropy,
118	                               (const unsigned char *)"mimo_client", 11);
119	  if (ret != 0) return -1;
120	
121	  ret = mbedtls_ssl_config_defaults(&g_tls_ctx.conf,
122	                                     MBEDTLS_SSL_IS_CLIENT,
123	                                     MBEDTLS_SSL_TRANSPORT_STREAM,
124	                                     MBEDTLS_SSL_PRESET_DEFAULT);
125	  if (ret != 0) return -1;
126	
127	  mbedtls_ssl_conf_authmode(&g_tls_ctx.conf, MBEDTLS_SSL_VERIFY_NONE);
128	  mbedtls_ssl_conf_rng(&g_tls_ctx.conf, mbedtls_ctr_drbg_random,
129	                        &g_tls_ctx.ctr_drbg);
130	
131	  g_tls_ready = true;
132	  return 0;
133	}
134	
135	static void tls_deinit(void)
136	{
137	  if (!g_tls_ready) return;
138	  mbedtls_ssl_config_free(&g_tls_ctx.conf);
139	  mbedtls_ctr_drbg_free(&g_tls_ctx.ctr_drbg);
140	  mbedtls_entropy_free(&g_tls_ctx.entropy);
141	  g_tls_ready = false;
142	}
143	
144	static int tls_connect_socket(const char *hostname, const char *port,
145	                               struct tls_conn_s **connp)
146	{
147	  struct tls_conn_s *conn;
148	  struct hostent *he;
149	  struct sockaddr_in server;
150	  int portnum;
151	  int ret;
152	  int fd;
153	
154	  he = gethostbyname(hostname);
155	  if (!he)
156	    {
157	      fprintf(stderr, "[mimo_client] DNS resolve failed for %s\n", hostname);
158	      return -EIO;
159	    }
160	
161	  fd = socket(AF_INET, SOCK_STREAM, 0);
162	  if (fd < 0)
163	    {
164	      fprintf(stderr, "[mimo_client] socket() failed: %d\n", errno);
165	      return -EIO;
166	    }
167	
168	  portnum = atoi(port);
169	  memset(&server, 0, sizeof(server));
170	  server.sin_family = AF_INET;
171	  server.sin_port = htons(portnum);
172	  memcpy(&server.sin_addr, he->h_addr_list[0], he->h_length);
173	
174	  if (connect(fd, (struct sockaddr *)&server, sizeof(server)) < 0)
175	    {
176	      fprintf(stderr, "[mimo_client] TCP connect failed: %d\n", errno);
177	      close(fd);
178	      return -EIO;
179	    }
180	
181	  /* Allocate connection wrapper */
182	
183	  conn = calloc(1, sizeof(*conn));
184	  if (!conn)
185	    {
186	      close(fd);
187	      return -ENOMEM;
188	    }
189	
190	  conn->fd = fd;
191	  mbedtls_ssl_init(&conn->ssl);
192	
193	  ret = mbedtls_ssl_setup(&conn->ssl, &g_tls_ctx.conf);
194	  if (ret != 0) goto err;
195	
196	  ret = mbedtls_ssl_set_hostname(&conn->ssl, hostname);
197	  if (ret != 0) goto err;
198	
199	  mbedtls_ssl_set_bio(&conn->ssl, &conn->fd, bio_send, bio_recv, NULL);
200	
201	  while ((ret = mbedtls_ssl_handshake(&conn->ssl)) != 0)
202	    {
203	      if (ret != MBEDTLS_ERR_SSL_WANT_READ &&
204	          ret != MBEDTLS_ERR_SSL_WANT_WRITE)
205	        {
206	          fprintf(stderr, "[mimo_client] TLS handshake failed: -0x%x\n", -ret);
207	          goto err;
208	        }
209	    }
210	
211	  *connp = conn;
212	  return 0;
213	
214	err:
215	  mbedtls_ssl_free(&conn->ssl);
216	  close(conn->fd);
217	  free(conn);
218	  return -EIO;
219	}
220	
221	static void tls_disconnect(struct tls_conn_s *conn)
222	{
223	  if (!conn) return;
224	  mbedtls_ssl_close_notify(&conn->ssl);
225	  mbedtls_ssl_free(&conn->ssl);
226	  close(conn->fd);
227	  free(conn);
228	}
229	
230	static int tls_write(struct tls_conn_s *conn, const void *buf, size_t len)
231	{
232	  int ret = mbedtls_ssl_write(&conn->ssl, buf, len);
233	  if (ret < 0)
234	    {
235	      return (ret == MBEDTLS_ERR_SSL_WANT_WRITE) ? 0 : -EIO;
236	    }
237	
238	  return ret;
239	}
240	
241	static int tls_read(struct tls_conn_s *conn, void *buf, size_t len)
242	{
243	  int ret = mbedtls_ssl_read(&conn->ssl, buf, len);
244	  if (ret < 0)
245	    {
246	      if (ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY ||
247	          ret == MBEDTLS_ERR_SSL_WANT_READ)
248	        {
249	          return 0;
250	        }
251	
252	      return -EIO;
253	    }
254	
255	  return ret;
256	}
