260	/****************************************************************************
261	 * Private Functions - HTTP Response Parser
262	 ****************************************************************************/
263	
264	static int parse_chat_response(const char *json_str,
265	                               struct mimo_rsp_s *rsp)
266	{
267	  cJSON *root;
268	  cJSON *choices;
269	  cJSON *choice;
270	  cJSON *message;
271	  cJSON *content;
272	  cJSON *audio;
273	  cJSON *audio_data_item;
274	
275	  root = cJSON_Parse(json_str);
276	  if (!root)
277	    {
278	      snprintf(rsp->error_msg, sizeof(rsp->error_msg),
279	               "JSON parse error");
280	      rsp->error_code = -1;
281	      return -1;
282	    }
283	
284	  cJSON *error = cJSON_GetObjectItem(root, "error");
285	  if (error)
286	    {
287	      cJSON *errmsg = cJSON_GetObjectItem(error, "message");
288	      snprintf(rsp->error_msg, sizeof(rsp->error_msg), "API: %s",
289	               errmsg ? errmsg->valuestring : "unknown");
290	      rsp->error_code = -2;
291	      cJSON_Delete(root);
292	      return -1;
293	    }
294	
295	  choices = cJSON_GetObjectItem(root, "choices");
296	  if (!choices || cJSON_GetArraySize(choices) == 0)
297	    {
298	      snprintf(rsp->error_msg, sizeof(rsp->error_msg),
299	               "No choices in response");
300	      rsp->error_code = -3;
301	      cJSON_Delete(root);
302	      return -1;
303	    }
304	
305	  choice = cJSON_GetArrayItem(choices, 0);
306	  message = cJSON_GetObjectItem(choice, "message");
307	  if (!message)
308	    {
309	      snprintf(rsp->error_msg, sizeof(rsp->error_msg),
310	               "No message in choice");
311	      rsp->error_code = -4;
312	      cJSON_Delete(root);
313	      return -1;
314	    }
315	
316	  content = cJSON_GetObjectItem(message, "content");
317	  if (content && content->valuestring)
318	    {
319	      rsp->content = strdup(content->valuestring);
320	    }
321	
322	  audio = cJSON_GetObjectItem(message, "audio");
323	  if (audio)
324	    {
325	      audio_data_item = cJSON_GetObjectItem(audio, "data");
326	      if (audio_data_item && audio_data_item->valuestring)
327	        {
328	          rsp->audio_data = (uint8_t *)strdup(audio_data_item->valuestring);
329	          rsp->audio_len = strlen((char *)rsp->audio_data);
330	        }
331	    }
332	
333	  cJSON_Delete(root);
334	  return 0;
335	}
