337	/****************************************************************************
338	 * Private Functions - HTTP POST
339	 ****************************************************************************/
340	
341	/**
342	 * Extract HTTP status code from response header.
343	 * Returns 0 if not found.
344	 */
345	
346	static int extract_http_status(const char *response)
347	{
348	  const char *p = response;
349	
350	  /* Expect "HTTP/1.x NNN" */
351	
352	  if (strncmp(p, "HTTP/", 5) != 0) return 0;
353	
354	  p = strchr(p, ' ');
355	  if (!p) return 0;
356	
357	  return atoi(p + 1);
358	}
359	
360	/**
361	 * Find the body start in an HTTP response (after \r\n\r\n).
362	 */
363	
364	static const char *find_body(const char *response)
365	{
366	  const char *p = strstr(response, "\r\n\r\n");
367	  if (!p) return response;  /* No header separator, treat all as body */
368	  return p + 4;
369	}
