392	/****************************************************************************
393	 * Name: mimo_http_post
394	 *
395	 * Description:
396	 *   POST a JSON body to the MiMo API endpoint via raw socket + TLS.
397	 *   Returns 0 on success, <0 on error. rsp is populated with parsed result.
398	 *
399	 ****************************************************************************/
400	
401	int mimo_http_post(const char *json_body, struct mimo_rsp_s *rsp)
402	{
403	#ifdef CONFIG_CRYPTO_MBEDTLS
404	  struct tls_conn_s *conn = NULL;
405	  char request[HTTP_SEND_BUF_SIZE];
406	  char *response = NULL;
407	  size_t resp_len = 0;
408	  size_t resp_cap = 0;
409	  char recv_buf[HTTP_RECV_BUF_SIZE];
410	  const char *body_start;
411	  int http_status;
412	  int ret;
413	  int n;
414	
415	  memset(rsp, 0, sizeof(*rsp));
416	
417	  /* Connect via TLS */
418	
419	  ret = tls_connect_socket(MIMO_HOST, MIMO_PORT, &conn);
420	  if (ret < 0)
421	    {
422	      snprintf(rsp->error_msg, sizeof(rsp->error_msg),
423	               "TLS connect failed");
424	      rsp->error_code = ret;
425	      return -1;
426	    }
427	
428	  /* Build HTTP POST request */
429	
430	  snprintf(request, sizeof(request),
431	           "POST /v1/chat/completions HTTP/1.1\r\n"
432	           "Host: %s\r\n"
433	           "Authorization: Bearer %s\r\n"
434	           "Content-Type: application/json\r\n"
435	           "Content-Length: %zu\r\n"
436	           "Connection: close\r\n"
437	           "\r\n"
438	           "%s",
439	           MIMO_HOST, MIMO_API_KEY, strlen(json_body), json_body);
440	
441	  /* Send request */
442	
443	  ret = tls_write(conn, request, strlen(request));
444	  if (ret < 0)
445	    {
446	      snprintf(rsp->error_msg, sizeof(rsp->error_msg),
447	               "TLS send failed");
448	      rsp->error_code = ret;
449	      tls_disconnect(conn);
450	      return -1;
451	    }
452	
453	  /* Read response */
454	
455	  while ((n = tls_read(conn, recv_buf, sizeof(recv_buf) - 1)) > 0)
456	    {
457	      if (resp_len + n + 1 > resp_cap)
458	        {
459	          size_t newcap = resp_cap ? resp_cap * 2 : HTTP_RECV_BUF_SIZE;
460	          if (newcap > HTTP_MAX_RESPONSE)
461	            {
462	              break;  /* Too large */
463	            }
464	
465	          char *newbuf = realloc(response, newcap);
466	          if (!newbuf) break;
467	          response = newbuf;
468	          resp_cap = newcap;
469	        }
470	
471	      memcpy(response + resp_len, recv_buf, n);
472	      resp_len += n;
473	      response[resp_len] = '\0';
474	    }
475	
476	  tls_disconnect(conn);
477	
478	  if (!response)
479	    {
480	      snprintf(rsp->error_msg, sizeof(rsp->error_msg),
481	               "Empty response");
482	      rsp->error_code = -5;
483	      return -1;
484	    }
485	
486	  /* Parse HTTP status */
487	
488	  http_status = extract_http_status(response);
489	  rsp->http_status = http_status;
490	
491	  if (http_status != 200)
492	    {
493	      body_start = find_body(response);
494	      snprintf(rsp->error_msg, sizeof(rsp->error_msg),
495	               "HTTP %d: %.200s", http_status,
496	               body_start ? body_start : "(empty)");
497	      rsp->error_code = http_status;
498	      free(response);
499	      return -1;
500	    }
501	
502	  /* Find and parse JSON body */
503	
504	  body_start = find_body(response);
505	  if (!body_start || strlen(body_start) == 0)
506	    {
507	      snprintf(rsp->error_msg, sizeof(rsp->error_msg),
