static int configure_net(void)
{
  struct sockaddr_in addr;
  struct ifreq ifr;
  int fd;

  fd = socket(AF_INET, SOCK_DGRAM, 0);
  if (fd < 0)
    {
      printf("[campilot] socket failed: %d\n", errno);
      return -1;
    }

  memset(&ifr, 0, sizeof(ifr));
  strlcpy(ifr.ifr_name, "eth0", IFNAMSIZ);

  /* Set IP: 10.192.228.200 */
  memset(&addr, 0, sizeof(addr));
  addr.sin_family = AF_INET;
  addr.sin_addr.s_addr = inet_addr("10.192.228.200");
  memcpy(&ifr.ifr_addr, &addr, sizeof(addr));
  if (ioctl(fd, SIOCSIFADDR, &ifr) < 0)
    printf("[campilot] SIOCSIFADDR failed: %d\n", errno);

  /* Set netmask: 255.255.248.0 */
  addr.sin_addr.s_addr = inet_addr("255.255.248.0");
  memcpy(&ifr.ifr_addr, &addr, sizeof(addr));
  if (ioctl(fd, SIOCSIFNETMASK, &ifr) < 0)
    printf("[campilot] SIOCSIFNETMASK failed: %d\n", errno);

  /* Bring up */
  ifr.ifr_flags = IFF_UP;
  if (ioctl(fd, SIOCSIFFLAGS, &ifr) < 0)
    printf("[campilot] SIOCSIFFLAGS failed: %d\n", errno);

  close(fd);
  printf("[campilot] Static IP configured: 10.192.228.200/21\n");
  return 0;
}

