  fd = socket(AF_INET, SOCK_DGRAM, 0);
  if (fd < 0)
    {
      printf("[campilot] socket failed: %d\n", errno);
      return -1;
    }

  memset(&ifr, 0, sizeof(ifr));
  strlcpy(ifr.ifr_name, "eth0", IFNAMSIZ);

  /* Set netmask first (some stacks require this before setting IP) */
  memset(&addr, 0, sizeof(addr));
  addr.sin_family = AF_INET;
  addr.sin_addr.s_addr = inet_addr("255.255.248.0");
  memcpy(&ifr.ifr_addr, &addr, sizeof(addr));
  ret = ioctl(fd, SIOCSIFNETMASK, (unsigned long)&ifr);
  printf("[campilot] SIOCSIFNETMASK: %d\n", ret);

  /* Set IP */
  addr.sin_addr.s_addr = inet_addr("**.***.***.***");
  memcpy(&ifr.ifr_addr, &addr, sizeof(addr));
  ret = ioctl(fd, SIOCSIFADDR, (unsigned long)&ifr);
  printf("[campilot] SIOCSIFADDR: %d\n", ret);

  /* Set gateway */
  addr.sin_addr.s_addr = inet_addr("**.***.***.*");
  memcpy(&ifr.ifr_addr, &addr, sizeof(addr));
  ret = ioctl(fd, SIOCSIFDSTADDR, (unsigned long)&ifr);
  printf("[campilot] SIOCSIFDSTADDR: %d\n", ret);

  /* Read back IP to verify */
  ret = ioctl(fd, SIOCGIFADDR, (unsigned long)&ifr);
  if (ret >= 0)
    {
      struct sockaddr_in *sin = (struct sockaddr_in *)&ifr.ifr_addr;
      printf("[campilot] SIOCGIFADDR -> %s\n", inet_ntoa(sin->sin_addr));
    }

  close(fd);
  return 0;
}

