803	   * (the JPEG encoder) and enables CLIC 21 turns that asserted line into an
804	   * unstoppable level storm - shared_intr_isr only knows the JPEG vector, the
805	   * JPEG status register reads 0 (no encode), nothing is cleared, and the
806	   * dispatch re-fires forever ('k' flood).  This was the root cause of the
807	   * jpegenc hang.
808	   *
809	   * Disable UART0's peripheral interrupt and re-route its source to the
810	   * reserved INT_MUX_DISABLED_INTNO (CPU int 6, never enabled) so UART0 can
811	   * never assert into any CLIC line again. */
812	  {
813	    volatile uint32_t *uart = (volatile uint32_t *)0x500CA000; /* DR_REG_UART0_BASE */
814	    uart[0x10 / 4] = 0xffffffffu;  /* UART_INT_CLR: clear every pending bit */
815	    uart[0x0c / 4] = 0;            /* UART_INT_ENA: mask the peripheral */
816	    volatile uint32_t *map = (volatile uint32_t *)0x500D6000;  /* INTR_CORE0 */
817	    map[31] = (map[31] & ~0x3Fu) | 6u;  /* source 31 -> INT_MUX_DISABLED_INTNO */
