Summary:
1. Primary Request and Intent:
   用户说"继续"（continue），继续执行M2里程碑：在ESP32-P4板上验证campilot的MiMo API调用。同时还要求"总结一下当前进展,并更新到文档中"。最终目标是让 `campilot text hello` 命令通过串口成功调用MiMo API并返回结果。用户授权可直接操作设备。默认输出中文，commit message纯ASCII英文，代码注释英文。

2. Key Technical Concepts:
   - **Vela build system**: `source build/envsetup.sh && lunch <target> && m` — NOT `./build.sh` directly. Binary dir is `out/espressif_esp32p4-function-ev-board_openvela/`
   - **ESP32-P4 ROM bootloader**: Flash offset 0x2000, USB JTAG/serial debug unit
   - **RISC-V rv32imac (no FPU)**: uint32_t is `unsigned long` not `unsigned int` — printf format specifiers differ
   - **-Werror -Wundef**: Platform builds with -Werror, so any warning is fatal. mbedTLS headers check `MBEDTLS_SSL_DTLS_CONNECTION_ID_COMPAT` which requires explicit definition
   - **esp_timer**: EMAC driver needs `esp_timer_create()` which calls `is_initialized()` checking `s_timer_task > 0`. If esp_timer_init hasn't been called (its an ESP_SYSTEM_INIT_FN with SECONDARY priority, mask ESP_TIMER_INIT_MASK, order 100), the timer creation fails
   - **NuttX ioctl network config**: `SIOCSIFADDR`, `SIOCSIFNETMASK`, `SIOCSIFDSTADDR` via `struct ifreq` with AF_INET socket using `<nuttx/net/ioctl.h>`
   - **netlib.h inaccessible from board code**: Board bringup.c can't include `netutils/netlib.h` because `apps/include` is not in its include path

3. Files and Code Sections:

   - **`/data/work/work/workspace/openvela_workspace/nuttx/boards/risc-v/esp32p4/esp32p4-function-ev-board/src/esp32p4_bringup.c`** (EDITED - current state)
     - Replaced netlib-based `configure_net()` with raw ioctl approach
     - Critical for getting IP on eth0 before campilot runs
     - Current code:
     ```c
     #include <sys/socket.h>
     #include <sys/ioctl.h>
     #include <netinet/in.h>
     #include <arpa/inet.h>
     #include <net/if.h>
     #include <nuttx/net/ioctl.h>

     #ifdef CONFIG_EXAMPLES_CAMPILOT
     extern int campilot_main(int argc, char *argv[]);

     static int configure_net(void)
     {
       struct sockaddr_in addr;
       struct ifreq ifr;
       int fd;
       int ret;

       fd = socket(AF_INET, SOCK_DGRAM, 0);
       if (fd < 0) { printf("[campilot] socket failed: %d\n", errno); return -1; }

       memset(&ifr, 0, sizeof(ifr));
       strlcpy(ifr.ifr_name, "eth0", IFNAMSIZ);

       /* Set netmask first */
       memset(&addr, 0, sizeof(addr));
       addr.sin_family = AF_INET;
       addr.sin_addr.s_addr = inet_addr("255.255.248.0");
       memcpy(&ifr.ifr_addr, &addr, sizeof(addr));
       ret = ioctl(fd, SIOCSIFNETMASK, (unsigned long)&ifr);
       printf("[campilot] SIOCSIFNETMASK: ret=%d errno=%d\n", ret, errno);

       /* Set IP */
       addr.sin_addr.s_addr = inet_addr("10.228.196.10");
       memcpy(&ifr.ifr_addr, &addr, sizeof(addr));
       ret = ioctl(fd, SIOCSIFADDR, (unsigned long)&ifr);
       printf("[campilot] SIOCSIFADDR: ret=%d errno=%d\n", ret, errno);

       /* Set gateway */
       addr.sin_addr.s_addr = inet_addr("10.228.192.1");
       memcpy(&ifr.ifr_addr, &addr, sizeof(addr));
       ret = ioctl(fd, SIOCSIFDSTADDR, (unsigned long)&ifr);
       printf("[campilot] SIOCSIFDSTADDR: ret=%d errno=%d\n", ret, errno);

       /* Read back IP */
       ret = ioctl(fd, SIOCGIFADDR, (unsigned long)&ifr);
       if (ret >= 0) {
         struct sockaddr_in *sin = (struct sockaddr_in *)&ifr.ifr_addr;
         printf("[campilot] SIOCGIFADDR verify: %s\n", inet_ntoa(sin->sin_addr));
       } else {
         printf("[campilot] SIOCGIFADDR failed: ret=%d errno=%d\n", ret, errno);
       }

       /* Read back netmask */
       ret = ioctl(fd, SIOCGIFNETMASK, (unsigned long)&ifr);
       if (ret >= 0) {
         struct sockaddr_in *sin = (struct sockaddr_in *)&ifr.ifr_addr;
         printf("[campilot] SIOCGIFNETMASK verify: %s\n", inet_ntoa(sin->sin_addr));
       }

       close(fd);
       printf("[campilot] network configured\n");
       return 0;
     }

     static int campilot_auto(int argc, char *argv[])
     {
       int ret;
       printf("[campilot] auto-test starting...\n");
       usleep(500000);
       ret = configure_net();
       if (ret < 0) printf("[campilot] net config failed\n");
       printf("[campilot] === text hello ===\n");
       char *cargs[] = {"campilot", "text", "hello", NULL};
       campilot_main(3, cargs);
       printf("[campilot] auto-test done\n");
       return 0;
     }
     #endif
