494	  esp_err_t err = esp_timer_init();
495	  if (err != ESP_OK)
496	    {
497	      _err("esp_timer_init failed: %d\n", err);
498	      return ERROR;
499	    }
500	
501	  g_hr_timer_initialized = true;
502	  return OK;
503	}
