46	uint64_t systimer_hal_get_counter_value(systimer_hal_context_t *hal, uint32_t counter_id)
47	{
48	    uint32_t lo, lo_start, hi;
49	    /* Set the "update" bit and wait for acknowledgment */
50	    systimer_ll_counter_snapshot(hal->dev, counter_id);
51	    while (!systimer_ll_is_counter_value_valid(hal->dev, counter_id));
52	    /* Read LO, HI, then LO again, check that LO returns the same value.
53	     * This accounts for the case when an interrupt may happen between reading
54	     * HI and LO values, and this function may get called from the ISR.
55	     * In this case, the repeated read will return consistent values.
56	     */
57	    lo_start = systimer_ll_get_counter_value_low(hal->dev, counter_id);
58	    do {
59	        lo = lo_start;
60	        hi = systimer_ll_get_counter_value_high(hal->dev, counter_id);
61	        lo_start = systimer_ll_get_counter_value_low(hal->dev, counter_id);
62	    } while (lo_start != lo);
63	
64	    systimer_counter_value_t result = {
65	        .lo = lo,
66	        .hi = hi
67	    };
68	
69	    return result.val;
70	}
