92	{
93	    int64_t offset = hal->us_to_ticks(1) * 2;
94	    uint64_t now_time = systimer_hal_get_counter_value(hal, 0);
95	    uint64_t timestamp_ticks = hal->us_to_ticks(timestamp);
96	    systimer_counter_value_t alarm = { .val = MAX(timestamp_ticks, now_time + offset) };
97	    do {
98	        systimer_ll_enable_alarm(hal->dev, alarm_id, false);
99	        systimer_ll_set_alarm_target(hal->dev, alarm_id, alarm.val);
100	        systimer_ll_enable_alarm(hal->dev, alarm_id, true);
101	        now_time = systimer_hal_get_counter_value(hal, 0);
102	        int64_t delta = (int64_t)alarm.val - (int64_t)now_time;
103	        if (delta <= 0 && !systimer_ll_is_alarm_int_fired(hal->dev, alarm_id)) {
104	            // new alarm is less than the counter and the interrupt flag is not set
105	            offset += -1 * delta + hal->us_to_ticks(1) * 2;
106	            alarm.val = now_time + offset;
107	        } else {
108	            // finish if either (alarm > counter) or the interrupt flag is already set.
109	            break;
110	        }
111	    } while (1);
112	}
