201	    if (apb_ticks_per_us != hal->us_to_ticks(1)) {
202	        HAL_ASSERT((hal->us_to_ticks(1) % apb_ticks_per_us) == 0 && "TICK_PER_US should be divisible by APB frequency (in MHz)");
