291	  /* Boot delay before the RAM marker dump.  The USB-Serial-JTAG console
292	   * re-enumerates on a hard reset, so a fast boot prints the M: dump before
293	   * a monitor can attach.  Hold ~8s here so the post-hang marker dump is
294	   * reliably captured.  up_udelay() is calibrated via BOARD_LOOPSPERMSEC; if
295	   * the calibration is off by a few x the window is still several seconds. */
296	
297	  up_udelay(8000000);  /* ~8 s */
