315	    uint32_t shr = *((volatile uint32_t *)0x5010ffd8);  /* shared_intr_isr run count */
316	    uint32_t src = *((volatile uint32_t *)0x5010ffcc);  /* last dispatched shared source */
317	    uint32_t intno = *((volatile uint32_t *)0x5010ffdc);  /* shared vector's CPU int */
318	    uint32_t flgs = *((volatile uint32_t *)0x5010ffbc);  /* shared vd->flags */
319	    uint32_t smask = *((volatile uint32_t *)0x5010ffc0); /* first sh_vec statusmask */
