183	static int configure_net(void)
184	{
185	  struct sockaddr_in addr;
186	  struct ifreq ifr;
187	  int fd;
188	  int ret;
189	
190	  fd = socket(AF_INET, SOCK_DGRAM, 0);
191	  if (fd < 0)
192	    {
193	      printf("[campilot] socket failed: %d\n", errno);
194	      return -1;
195	    }
196	
197	  memset(&ifr, 0, sizeof(ifr));
198	  strlcpy(ifr.ifr_name, "eth0", IFNAMSIZ);
199	
200	  /* Set netmask first */
201	  memset(&addr, 0, sizeof(addr));
202	  addr.sin_family = AF_INET;
203	  addr.sin_addr.s_addr = inet_addr("255.255.248.0");
204	  memcpy(&ifr.ifr_addr, &addr, sizeof(addr));
205	  ret = ioctl(fd, SIOCSIFNETMASK, (unsigned long)&ifr);
206	  printf("[campilot] SIOCSIFNETMASK: ret=%d errno=%d\n", ret, errno);
207	
208	  /* Set IP */
209	  addr.sin_addr.s_addr = inet_addr("10.192.228.200");
210	  memcpy(&ifr.ifr_addr, &addr, sizeof(addr));
211	  ret = ioctl(fd, SIOCSIFADDR, (unsigned long)&ifr);
212	  printf("[campilot] SIOCSIFADDR: ret=%d errno=%d\n", ret, errno);
213	
214	  /* Set gateway */
215	  addr.sin_addr.s_addr = inet_addr("10.192.224.1");
216	  memcpy(&ifr.ifr_addr, &addr, sizeof(addr));
217	  ret = ioctl(fd, SIOCSIFDSTADDR, (unsigned long)&ifr);
218	  printf("[campilot] SIOCSIFDSTADDR: ret=%d errno=%d\n", ret, errno);
219	
220	  /* Read back IP */
221	  ret = ioctl(fd, SIOCGIFADDR, (unsigned long)&ifr);
222	  if (ret >= 0)
223	    {
224	      struct sockaddr_in *sin = (struct sockaddr_in *)&ifr.ifr_addr;
225	      printf("[campilot] SIOCGIFADDR verify: %s\n", inet_ntoa(sin->sin_addr));
226	    }
227	  else
228	    {
229	      printf("[campilot] SIOCGIFADDR failed: ret=%d errno=%d\n", ret, errno);
230	    }
231	
232	  /* Read back netmask */
233	  ret = ioctl(fd, SIOCGIFNETMASK, (unsigned long)&ifr);
234	  if (ret >= 0)
235	    {
236	      struct sockaddr_in *sin = (struct sockaddr_in *)&ifr.ifr_addr;
237	      printf("[campilot] SIOCGIFNETMASK verify: %s\n", inet_ntoa(sin->sin_addr));
238	    }
239	
240	  close(fd);
241	  printf("[campilot] network configured\n");
242	  return 0;
243	}
