245	static int campilot_auto(int argc, char *argv[])
246	{
247	  int ret;
248	
249	  printf("[campilot] auto-test starting...\n");
250	
251	  /* Wait a bit for netinit thread to finish */
252	  usleep(500000);
253	
254	  ret = configure_net();
