esp_err_t esp_timer_impl_init(intr_handler_t alarm_handler)
{
    /* WORKAROUND: esp_timer_impl_early_init() is never called on NuttX
     * (the ESP_SYSTEM_INIT_FN hook is #ifndef __NuttX__), so systimer_hal
     * stays uninitialized: ticks_to_us/us_to_ticks are NULL and
     * esp_timer_impl_get_time() would jump to NULL (instruction fault).
     * Replicate the essential early_init steps here with direct LL calls
     * (ROM systimer_hal_* wrappers are unreliable under NuttX). */
    if (systimer_hal.dev == NULL) {
        systimer_hal.dev = &SYSTIMER;
    }
    if (systimer_hal.ticks_to_us == NULL) {
        systimer_hal.ticks_to_us = systimer_ticks_to_us;
