    *((volatile uint32_t *)0x5010ffa4) = (uint32_t)sc;
    *((volatile uint32_t *)0x5010ffa8) = usj[0x10 / 4];  /* USJ int_ena */
    *((volatile uint32_t *)0x5010ffac) = usj[0x0c / 4];  /* USJ int_st */
